import itertools
import json

riders = ['R', 'S', 'T', 'Y']
bikes = ['F', 'G', 'H', 'J']
perms = list(itertools.permutations(bikes))

solutions = []
for d1 in perms:
    a1 = dict(zip(riders, d1))
    for d2 in perms:
        a2 = dict(zip(riders, d2))
        # Each rider tests a different bicycle on day 2 than on day 1
        if any(a1[r] == a2[r] for r in riders):
            continue
        # Reynaldo cannot test F
        if a1['R'] == 'F' or a2['R'] == 'F':
            continue
        # Yuki cannot test J
        if a1['Y'] == 'J' or a2['Y'] == 'J':
            continue
        # Theresa must be one of the testers for H
        if 'H' not in (a1['T'], a2['T']):
            continue
        # Yuki's day-1 bicycle must be tested by Seamus on day 2
        if a2['S'] != a1['Y']:
            continue
        # Antecedent: Theresa tests J on the first day
        if a1['T'] != 'J':
            continue
        solutions.append((a1, a2))

options = {
    'A': lambda a1, a2: a2['R'] == 'G',
    'B': lambda a1, a2: a1['S'] == 'H',
    'C': lambda a1, a2: a2['Y'] == 'H',
    'D': lambda a1, a2: 'J' in (a1['S'], a2['S']),
    'E': lambda a1, a2: 'G' in (a1['T'], a2['T']),
}

possible = {}
for key, cond in options.items():
    possible[key] = any(cond(a1, a2) for a1, a2 in solutions)

true_opts = [k for k, v in possible.items() if v]

if len(true_opts) == 1:
    final_answer = true_opts[0]
else:
    final_answer = "UNSUPPORTED"

evidence = {
    "num_valid_schedules": len(solutions),
    "option_possible": possible,
    "possible_options": true_opts,
}

print(json.dumps({"final_answer": final_answer, "evidence": evidence}, sort_keys=True))
